create or replace function private.record_inventory_sale(p_product_id uuid,p_quantity integer,p_order_id uuid,p_seller_id uuid) returns void language plpgsql security definer set search_path to '' as $$ begin if p_quantity<=0 then raise exception 'INVALID_INVENTORY_QUANTITY'; end if; insert into public.inventory_ledger(product_id,seller_id,quantity_change,reason,reference_type,reference_id,actor_id) values(p_product_id,p_seller_id,-p_quantity,'sale','checkout',p_order_id,(select auth.uid())); end; $$;
revoke all on function private.record_inventory_sale(uuid,integer,uuid,uuid) from public,anon,authenticated;
